from tabtally.errors import MoneyError
from tabtally.money import allocate

WHOLE_PERCENT = 100


def split_equally(cents: int, people: list[str]) -> dict[str, int]:
    _reject_duplicates(people)
    return dict(zip(people, allocate(cents, [1] * len(people))))


def split_by_percent(cents: int, percent_options: list[str]) -> dict[str, int]:
    """Split by options written as NAME=PCT, whose whole-number percentages add up to 100."""
    entries = [_parse_percent(option) for option in percent_options]
    people = [name for name, _ in entries]
    percents = [percent for _, percent in entries]
    _reject_duplicates(people)
    if sum(percents) != WHOLE_PERCENT:
        raise MoneyError(f"percentages must add up to {WHOLE_PERCENT}, not {sum(percents)}")
    return dict(zip(people, allocate(cents, percents)))


def _parse_percent(option: str) -> tuple[str, int]:
    name, separator, text = option.partition("=")
    if not name or not separator or not text.isascii() or not text.isdecimal():
        raise MoneyError(f"expected NAME=PCT with a whole number of percent: {option!r}")
    return name, int(text)


def _reject_duplicates(people: list[str]) -> None:
    duplicates = sorted({name for name in people if people.count(name) > 1})
    if duplicates:
        raise MoneyError(f"listed more than once: {', '.join(duplicates)}")

